<script setup lang="ts">
import {ref,onMounted} from 'vue';import {ElMessageBox} from 'element-plus';import {request} from '@/integration/service';const data=ref({categories:[],tags:[]}),names=ref({categories:'',tags:''});onMounted(async()=>data.value=await request('/api/studio/taxonomy'));async function add(kind){try{data.value=await request('/api/admin/taxonomy','POST',{kind,name:names.value[kind]});names.value[kind]='';}catch{}}async function rename(kind,old){let name;try{name=(await ElMessageBox.prompt('重命名会同步更新已有文章。','修改名称',{inputValue:old})).value;}catch{return;}try{data.value=await request('/api/admin/taxonomy','PUT',{kind,old,name});}catch{}}async function remove(kind,name){try{await ElMessageBox.confirm('删除未使用的分类或标签？',name);}catch{return;}try{data.value=await request('/api/admin/taxonomy','DELETE',{kind,name});}catch{}}
</script>
<template><div><span class="studio-eyebrow">PUT IDEAS IN ORDER</span><h1>分类与标签</h1><p class="taxonomy-note">作者使用这里的分类与标签。你也可以在发布文章时直接输入新名称并回车。</p><div class="taxonomy-grid"><el-card v-for="kind in ['categories','tags']" :key="kind"><h2>{{kind==='categories'?'文章分类':'文章标签'}}</h2><form @submit.prevent="add(kind)"><el-input v-model="names[kind]" :placeholder="kind==='categories'?'例如：折腾笔记':'例如：Vue / 旅行 / 通关感想'" maxlength="60" required/><el-button native-type="submit" type="primary">新增</el-button></form><div v-for="name in data[kind]" :key="name" class="taxonomy-row"><b>{{name}}</b><el-button text @click="rename(kind,name)">重命名</el-button><el-button text type="danger" @click="remove(kind,name)">删除</el-button></div></el-card></div></div></template>
<style scoped>.taxonomy-note{margin:18px 0 25px;color:var(--studio-muted);font-size:13px}.taxonomy-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.taxonomy-grid h2{font-size:18px}.taxonomy-grid form{display:flex;gap:10px;margin:20px 0}.taxonomy-row{display:flex;align-items:center;border-top:1px solid var(--studio-line);padding:8px 0;font-size:13px}.taxonomy-row b{flex:1}@media(max-width:750px){.taxonomy-grid{grid-template-columns:1fr}}</style>
